monday = ["a.txt"]
tuesday = ["b.txt"]
wednesday = ["a.txt", "d.txt"]

print("Sunday full backup: everything")
since_full = []
for day, changed in [("Monday", monday), ("Tuesday", tuesday), ("Wednesday", wednesday)]:
    for name in changed:
        if name not in since_full:
            since_full.append(name)
    print(day, "incremental:", changed, "| differential:", since_full)
